        "sourceText": "84. 투자매매업자 및 투자중개업자의 신용공여에 대한 설명 중 옳지 못한 것은? (★★☆)\n① 투자매매업자 또는 투자중개업자는 투자자의 신용상태 및 종목별 거래상황 등을 고려하\n여 신용공여금액의 100분의 140 이상에 상당하는 담보를 징구하여야 한다. 다만 매도되\n었거나 환매청구된 예탁증권을 담보로 하여 매도금액 또는 환매금액 한도 내에서 융자를\n하는 경우에는 그러하지 아니하다.\n② 투자매매업자 또는 투자중개업자의 총 신용공여 규모는 자기자본의 범위 이내로 하되,\n신용공여 종류별로 투자매매업자 또는 투자중개업자의 구체적인 한도 및 계산방식은 금\n융위원회 위원장이 따로 결정할 수 있다.\n③ 상장채권 및 공모파생결합증권(주가연계증권에 한함)의 담보평가는 2 이상의 채권평가회\n사가 제공하는 가격정보를 기초로 투자매매업자 또는 투자중개업자가 산정한 가격으로\n한다.\n④ 거래소가 투자주의종목, 투자경고종목, 투자위험종목 또는 관리종목으로 지정한 증권은\n신규의 신용거래를 할 수 없다.",
