        "sourceText": "★☆☆\n4. 다음 중 경기확산지수(DI)에 대한 설명으로 거리가 먼 것은?\n① 경기변동의 진폭이나 속도는 측정하지 않고 변화 방향만을 파악하는 것이다.\n② 경기국면의 판단 및 예측과 경기의 전환점을 식별하기 위한 지표이다.\n③ DI가 50% 이상이면 경기 상승국면이다.\n④ 경기확산지수가 60에서 100으로 상승한 경우 경기확장속도가 100/60=약1.7배 빠르다고\n볼 수 있다.",
