        "question": "ISA(개인종합자산관리계좌)에 대한 설명이다. 틀린 것으로 연결한 것은?\n가. 일반형의 경우 금융소득종합과세 대상자가 아닐 경우 소득이 없어도 가입이 가능한데,\n이때 금융소득종합과세 대상자 여부의 판단은 직전 연도를 기준으로 한다.\n나. ISA의 의무가입기간은 3년이며 의무가입기간이 지나면 비과세 등의 세제혜택을 받을 수\n있는데, 서민형의 경우 통산순이익 기준 400만원까지 비과세 혜택을 받으며 400만 원을\n초과하는 통산순이익은 분리과세율(지방세 포함 9.9%)이 적용된다.\n다. 금융회사가 가입자의 위험성향과 자금운용목표를 고려하여 제시하는 모델포트폴리오 중\n하나를 선택하여 투자하는 방식은 중개형 ISA이다.",
