        "sourceText": "★★★\n39. 주식워런트증권(ELW)의 가격구조와 관련하여, 보기에 대한 설명으로 틀린 것은?\n주식워런트증권 가격=내재가치(행사가치)+시간가치\n⑤ 행사가치는 권리를 행사함으로써 얻을 수 있는 이익으로 내재가치라고 할 수 있으며,\n콜워런트의 행사가치(내재가치)는 ‘기초자산가격-권리행사가격’이다.\n⑥ 시간가치는 만기까지의 잔존기간 동안 기초자산의 변동성 등에 따라 얻게 될 기대가치에\n해당한다.\n⑦ 내재가치가 0보다 커서 현재 권리행사 가능 구간으로서 돈이 되는 영역을 외가격이라\n한다.\n⑧ 콜워런트와 풋워런트 모두 만기에 근접할수록 시간가치는 감소하여 0(제로)에 수렴한다.",
